<script setup lang="ts">
import {
  IonButton,
  IonContent,
  IonPage,
  IonTextarea,
  IonToast,
  useIonRouter,
} from '@ionic/vue'
import { onUnmounted, ref, watch } from 'vue'
import { Uploader } from 'vant'

import type { UploaderAfterRead } from 'vant/lib/uploader/types'
import { useRouter } from 'vue-router'
import { storeToRefs } from 'pinia'
import AvatarSettingTip from './createUniverse/modal/AvatarSettingTip.vue'
import { useCreateUniverseStore } from '@/store/createUniverseStore'
import CommonHeader from '@/components/CommonHeader.vue'
import CardContainer from '@/components/CardContainer.vue'
import CheckIconBlack from '@/components/svg/CheckIconBlack.vue'
import UploadImageIcon from '@/components/svg/UploadImageIcon.vue'
import { characterService } from '@/services/character'
import type { CharacterAvatarResponse } from '@/types/character'

// 加载几个默认模版图片
import pose0 from '@/assets/pose/avatar_pose_0.png'
import pose1 from '@/assets/pose/avatar_pose_1.png'
import pose2 from '@/assets/pose/avatar_pose_2.png'
import pose3 from '@/assets/pose/avatar_pose_3.png'
import pose4 from '@/assets/pose/avatar_pose_4.png'
import pose5 from '@/assets/pose/avatar_pose_5.png'
import pose6 from '@/assets/pose/avatar_pose_6.png'
import pose7 from '@/assets/pose/avatar_pose_7.png'
import SignedImg from '@/components/SignedImg.vue'
import LoadingLottie from '@/components/LoadingLottie.vue'

const router = useRouter()
const ionRouter = useIonRouter()
const createUniverseStore = useCreateUniverseStore()
// store the uploaded avatar preview to the store
const { uploadedAvatarPreview, inEditCharacter, generatedUniverse }
  = storeToRefs(createUniverseStore)

const isLoading = ref(false)
const toastIsOpen = ref(false)
const toastMessage = ref('')
// ion content dom element
const wrapper = ref<typeof IonContent>()

// default pose images, only need the index
const poseImgs = [pose0, pose1, pose2, pose3, pose4, pose5, pose6, pose7]
const selectedPose = ref<number>(0)

// convert the id to number
const charId = +router.currentRoute.value.params.id
const char = generatedUniverse.value?.chars.find(char => char?.charId === charId)
const generatedImage = ref<CharacterAvatarResponse>({
  presignedUrl: char?.pose?.original || '',
  s3Prefix: '',
})
const uploadedImage = ref <string>()
const hasGeneratedImage = ref(false)

// the dom element
const promptInput = ref(null)
// the content of the prompt
const prompt = ref(char?.poseKeywords || '')

onUnmounted(() => {
  // reset the uploaded avatar preview
  createUniverseStore.setUploadedAvatarPreview(undefined)
})

// Handle generate the avatar when everything is ready
async function handleGenerate() {
  // scroll the page to the top
  if (wrapper.value) {
    wrapper.value.$el.scrollToTop()
  }

  isLoading.value = true
  try {
    let s3Url = ''
    console.debug('[handleGenerate] prompt', prompt.value)
    console.debug(uploadedAvatarPreview.value)
    if (uploadedAvatarPreview.value) {
      const { fileName, base64 } = uploadedAvatarPreview.value
      if (!base64) {
        return
      }
      // presigned uploaded avatar url
      const res = await characterService.presignAvatarUrl(fileName)
      s3Url = res.presignedUrl
      const file = uploadedAvatarPreview.value.file
      await characterService.uploadImage(res.presignedUrl, file!)
    }
    // update the character avatar
    const res = await characterService.generateCharacterDefaultAvatar(
      {
        charId,
        imageUrl: s3Url,
        keywords: prompt.value,
        poseType: selectedPose.value || 0,
      },
      {
        timeout: 1000 * 60 * 5,
      },
    )
    console.debug(res)
    hasGeneratedImage.value = true
    generatedImage.value = res
    isLoading.value = false
  }
  catch (error) {
    console.log(error)
    isLoading.value = false
  }
}

function handleSave() {
  // put the generated image to the inEditCharacter
  if (generatedImage.value.s3Prefix.length > 0) {
    if (inEditCharacter.value) {
      inEditCharacter.value.pose = {}
      inEditCharacter.value.pose.original = generatedImage.value.s3Prefix
      inEditCharacter.value.poseKeywords = prompt.value
    }
    ionRouter.back()
  }
}

watch(
  () => uploadedAvatarPreview.value,
  (newPreviewImg) => {
    if (newPreviewImg) {
      console.debug(newPreviewImg)
      uploadedImage.value = newPreviewImg.base64
    }
  }, { deep: true },
)

const afterRead: UploaderAfterRead = async (file: any) => {
  // 此时可以自行将文件上传至服务器
  if (!file?.file.name) {
    return
  }
  // convert the file to object url
  let url = URL.createObjectURL(file.file)
  // encode the url
  url = encodeURIComponent(url)

  createUniverseStore.setUploadedAvatarPreview({
    charId,
    fileUrl: url,
    fileName: file.file.name,
  })
  ionRouter.push(`/image-crop/${url}`)
}
</script>

<template>
  <ion-page>
    <ion-toast
      :is-open="toastIsOpen"
      :message="toastMessage"
      :duration="3000"
      position="middle"
      class="custom-toast"
      @did-dismiss="() => (toastIsOpen = false)"
    />
    <common-header title="Avatar Settings">
      <avatar-setting-tip />
    </common-header>
    <ion-content ref="wrapper" class="ion-padding">
      <loading-lottie v-if="isLoading" class="text-center" />
      <signed-img
        v-else
        class="block m-auto mt-2"
        :style="{ width: '180px' }"
        :src="generatedImage?.presignedUrl || ''"
      />
      <card-container>
        <p class="flex-shrink-0 text-4 fw-500 leading-6 text-nowrap">
          Keywords of the avatar*
        </p>
        <ion-textarea
          id="user_ideas_textarea"
          ref="promptInput"
          v-model="prompt"
          autocomplete="on"
          autocorrect="on"
          autocapitalize="on"
          :auto-grow="true"
          :error-text="$t('createUniversePage.isRequired')"
          :maxlength="1200"
          class="rounded-2 px-4 py-1 bg-input-bg-2 custom"
        />
      </card-container>
      <card-container>
        <p class="flex-shrink-0 text-4 fw-500 leading-6 text-nowrap">
          Import Image
        </p>
        <p class="text-on-bg-3 mb-4">
          You can import image to help build the avatar.
        </p>
        <div class="flex justify-center">
          <div
            v-if="uploadedImage"
            class="relative m-auto overflow-hidden rounded-2xl"
            :style="{ width: '154px' }"
          >
            <img
              :style="{ width: '154px' }"
              :src="uploadedImage"
            >
            <ion-button
              size="small"
              shape="round"
              class="w-10 absolute top-1 left-1 secondary-button"
              @click="ionRouter.push(`/image-crop/${uploadedAvatarPreview?.fileUrl}`)"
            >
              Edit
            </ion-button>
            <ion-button
              v-if="uploadedImage"
              size="small"
              shape="round"
              class="w-14 absolute top-1 right-1 secondary-button"
              @click="() => {
                uploadedImage = undefined
                createUniverseStore.setUploadedAvatarPreview(undefined)
              }"
            >
              Delete
            </ion-button>
          </div>
          <uploader
            v-else
            class="flex-1 relative mt-4"
            :style="{ width: uploadedImage != null ? '154px' : 'auto' }"
            :after-read="afterRead"
          >
            <div
              class="w-full px-4 py-1 upload-img-btn flex justify-center items-center"
            >
              <upload-image-icon class="mr-2" />
              Import Image
            </div>
          </uploader>
        </div>
      </card-container>
      <card-container override-class="px-0">
        <p class="flex-shrink-0 text-4 fw-500 leading-6 text-nowrap px-4">
          Multiple poses
        </p>
        <p class="text-on-bg-3 px-4">
          Select one pose you like the most for the character avatar
        </p>
        <div class="w-full overflow-x-auto flex whitespace-nowrap">
          <div
            v-for="(pose, index) in poseImgs"
            :key="`pose-${index}`"
            :class="`pose-wrapper relative bg-white rd-3 mx-1 mt-4 flex-shrink-0 ${
              index === 0 && 'ml-4'
            } ${index === poseImgs.length - 1 && 'mr-4'} ${
              selectedPose === index && 'selected'
            }`"
            :style="{ width: '154px' }"
            @click="selectedPose = index"
          >
            <img class="rd-3" :style="{ width: '154px' }" :src="pose">
            <check-icon-black
              v-if="selectedPose === index"
              class="absolute bottom-1 left-1"
            />
          </div>
        </div>
      </card-container>
      <ion-button
        shape="round"
        class="w-full mt-4 secondary-button"
        :disabled="isLoading"
        @click="handleGenerate"
      >
        {{
          isLoading
            ? "Generating"
            : generatedImage != null
              ? "Regenerate"
              : "Generate"
        }}
      </ion-button>
      <div :style="{ height: '160px' }" />
      <div
        v-if="hasGeneratedImage"
        slot="fixed" class="px-4 w-full bottom-0 pb-unsafe-area"
      >
        <ion-button
          shape="round"
          class="w-full"
          :disabled="generatedImage == null || isLoading"
          @click="handleSave"
        >
          Save
        </ion-button>
      </div>
    </ion-content>
  </ion-page>
</template>

